with ValidInventory as (select * from inventory where not (store_id in (1, 3) and last_restock >= '2024-10-07')), summary as (select case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end as last_restock_cohort, max(quantity) as max_quantity, round(stddev(quantity), 2) as stddev_quantity from ValidInventory group by case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end) select * from summary order by last_restock_cohort;
